use vstd::prelude::*;

verus! {

#[derive(Clone)]
pub struct Complex {
    pub real: i32,
    pub imag: i32,
}

//
// A little helper to talk about absolute‐value on i32 in specifications.
// Returns the nonnegative magnitude of x as a nat.
//
spec fn abs_i32(x: i32) -> nat {
    if x < 0 {
        (-x) as nat
    } else {
        x as nat
    }
}

//
// Predicate saying the imaginary part `im` is "close to zero"
// under the tolerance `tol`.  We fix machine‐epsilon = 2, so
// `|im| <= tol * 2`.
//
spec fn is_close(im: i32, tol: i32) -> bool {
    abs_i32(im) <= (tol * 2) as nat
}

//
// real_if_close:
//   Given an array `arr` of Complex numbers and a positive integer tolerance `tol`,
//   if *every* imaginary part is "close to zero" (|imag| <= tol*2),
//   produces a new array of the same length whose real parts agree
//   with the input and whose imaginary parts are all set to 0.
//   Otherwise, returns the original array unchanged.
//
//  Specifications:
//    1) The result has the same length as the input.
//    2) For all positions i, result[i].real == arr[i].real.
//    3) If *all* arr[i].imag == 0, then result == arr.  
//       (This follows from 2) and the fact that in the "close"‐branch
//        we also set imag=0 everywhere.)
//    4) If *all* imag parts are `is_close`, then the result's imag parts are all zero.
//
fn real_if_close(arr: Vec<Complex>, tol: i32) -> (result: Vec<Complex>)
    requires
        tol > 0,
    ensures
        result.len() == arr.len(),
    ensures
        forall |i: int|
            0 <= i && i < arr.len() ==>
            result.index(i).real == arr.index(i).real,
    ensures
        (forall |i: int|
            0 <= i && i < arr.len() ==>
            arr.index(i).imag == 0)
        ==> result == arr,
    ensures
        (forall |i: int|
            0 <= i && i < arr.len() ==>
            is_close(arr.index(i).imag, tol))
        ==>
        forall |i: int|
            0 <= i && i < arr.len() ==>
            result.index(i).imag == 0,
{
    let n = arr.len();

    // Compute whether every imag part is "close"
    let mut all_close: bool = true;
    let mut i: usize = 0;
    while i < n
        invariant
            0 <= i && i <= n,
            // all_close exactly means: for every j < i, arr[j].imag is close
            all_close == (forall |j: int| 0 <= j && j < i ==> is_close(arr.index(j).imag, tol)),
        decreases n - i,
    {
        let im = arr.index(i).imag;
        // compute absolute value at runtime
        let abs_im = if im < 0 { -im } else { im };
        if abs_im > tol * 2 {
            all_close = false;
        }
        i += 1;
    }

    if all_close {
        // build a new vector of length n with imag = 0
        let mut res: Vec<Complex> = Vec::new();
        res.reserve(n);
        let mut j: usize = 0;
        while j < n
            invariant
                0 <= j && j <= n,
                res.len() == j,
                // so far we have copied real parts and set imag = 0
                forall |k: int|
                    0 <= k && k < j ==>
                    res.index(k).real == arr.index(k).real &&
                    res.index(k).imag == 0,
            decreases n - j,
        {
            let r = arr.index(j).real;
            res.push(Complex { real: r, imag: 0 });
            j += 1;
        }
        result = res;
    } else {
        // not all were close, return the original
        result = arr;
    }
}

} // end verus!

